+    while (scheduler.next_q_block(q_block_idx, kv_base, num_kv_splits)) {
+      CUTE_TIE_DECL(q_pipeline.advance(), q_stage_idx, q_phase);
+      smem.full_q_barriers[q_stage_idx].wait(q_phase);
